CREATE TABLE IF NOT EXISTS "TherapistProfile" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "bio" TEXT NOT NULL,
  "qualifications" TEXT[],
  "yearsExp" INTEGER NOT NULL,
  "languages" TEXT[],
  "specializations" TEXT[],
  "rciNumber" TEXT NOT NULL,
  "sessionFee" INTEGER NOT NULL,
  "gender" TEXT,
  "clinicianType" TEXT,
  "rating" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "totalReviews" INTEGER NOT NULL DEFAULT 0,
  "isVerified" BOOLEAN NOT NULL DEFAULT false,
  "isActive" BOOLEAN NOT NULL DEFAULT true,
  "employmentType" "EmploymentType" NOT NULL DEFAULT 'FULL_TIME',
  "baseFeeIndividual" INTEGER,
  "baseFeeCouples" INTEGER,
  "baseFeePsychiatry" INTEGER,
  "secondSessionBonus" INTEGER,
  "thirdOnwardsBonus" INTEGER,
  "miscBonus" INTEGER,
  "nightSessionBonus" INTEGER,
  "saturdayBonus" INTEGER,
  "sundayBonus" INTEGER,
  "matchingEligible" BOOLEAN NOT NULL DEFAULT true,
  "directBookingEligible" BOOLEAN NOT NULL DEFAULT true,
  "compensationFields" JSONB,
  "documentUrls" TEXT[],
  "photoUrl" TEXT,
  "dateOfBirth" TIMESTAMP(3),
  "country" TEXT NOT NULL DEFAULT 'IN',
  "state" TEXT,
  "city" TEXT,
  "addressLine1" TEXT,
  "addressLine2" TEXT,
  "postalCode" TEXT,
  "emergencyName" TEXT,
  "emergencyPhone" TEXT,
  "emergencyRelation" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "TherapistProfile_pkey" PRIMARY KEY ("id")
);
